/* Generated by build.mjs. App state is only in localStorage, never in this cache. */
const VERSION=__VERSION__;
const FILES=__FILES__;
const INTEGRITY=__INTEGRITY__;
const PREFIX='phrase-pocket:'+self.registration.scope+':';
const CACHE=PREFIX+VERSION;
const base=self.registration.scope;
const assetURL=file=>new URL(file,base).href;
self.addEventListener('install',event=>{event.waitUntil((async()=>{
 const cache=await caches.open(CACHE);
 // An incomplete install never activates, so the previous working version stays usable.
 await cache.addAll(FILES.map(file=>new Request(assetURL(file),{cache:'reload',credentials:'same-origin',integrity:INTEGRITY[file]})));
})());});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{
 // A new version waits until the user applies it or all old windows close.
 for(const key of await caches.keys())if(key.startsWith(PREFIX)&&key!==CACHE)await caches.delete(key);
 await self.clients.claim();
})());});
self.addEventListener('fetch',event=>{
 const request=event.request,url=new URL(request.url);
 if(request.method!=='GET'||url.origin!==self.location.origin||!url.href.startsWith(base))return;
 event.respondWith((async()=>{
 const cache=await caches.open(CACHE);
 if(request.mode==='navigate'){
   const cached=await cache.match(assetURL('index.html'));if(cached)return cached;
 }
 const match=await cache.match(request,{ignoreSearch:true});
 return match||fetch(request);
})());
});
self.addEventListener('message',event=>{
 if(event.data?.type==='ACTIVATE_UPDATE'){
  event.waitUntil((async()=>{
   const cache=await caches.open(CACHE);
   if((await Promise.all(FILES.map(file=>cache.match(assetURL(file))))).every(Boolean))await self.skipWaiting();
  })());return;
 }
 if(event.data?.type!=='CHECK_OFFLINE'||!event.ports[0])return;
 event.waitUntil((async()=>{const cache=await caches.open(CACHE);const ready=(await Promise.all(FILES.map(file=>cache.match(assetURL(file))))).every(Boolean);event.ports[0].postMessage({type:'OFFLINE_READY',ready});})());
});
